import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷二","description":"周易經傳集解 - 周易經傳集解卷二","frontmatter":{"title":"周易經傳集解卷二","description":"周易經傳集解 - 周易經傳集解卷二"},"headers":[],"relativePath":"classics/jingchuan-jijie/003.md","filePath":"classics/jingchuan-jijie/003.md"}'),r={name:"classics/jingchuan-jijie/003.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷二",tabindex:"-1"},[n("周易經傳集解卷二 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷二","aria-label":"Permalink to “周易經傳集解卷二”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解卷二 ​宋林栗撰。序卦曰：「有天地，然後萬物生焉。盈天地之間者惟萬物，故受之以屯。屯者，盈也；屯者，物之始生也。」屯之成卦，變坤之初、五二爻而成也。變者何也？乾交於坤，故其象不得不變也。天地不交，萬物不生。乾坤既成列矣，必自其始交而言之。始交而成震，震在下而始然重卦之象，非三畫之震所能備也。若取諸重震，則非始交之義也。故自其交以至於通而言之。始通而成坎，坎在中為通。始乎震，通乎坎，物之所生也，故謂之屯。屯者，盈也，萬物盈乎天地之間者也。萬，盈數也，數之積也。自一至十，天地之數，而屯之畫具矣。屯者，物之始生也。物生之始，形質未定，其數已盈乎天地之間矣。是何也？震坎之中有坤艮之象焉。坤也者，萬物之所致養也。艮也者，萬物之所成終而成始也。則其盈滿天地，不亦宜乎？夫子所作十翼，先儒既取其釋彖、大小象、文言分系於經，學者便於尋繹。自漢以來，未之有改，而獨繫辭、說卦、序卦、雜卦至今為完篇。夫說卦止於八物，而繫辭領略綱紀，固不可得而分系之矣。若夫序、雜二篇，條陳其用，無所遺漏，宜與象彖同其離合，然而不之取者，序卦皆相因，雜卦皆相交。相因之義，近於淺易，相交之辭，幾於隱者，是以學者難言之，而又疑其未必然也。未必然者，妄也。楊雄有言曰：「聖人之言天也。」豈妄乎？夫序卦者，卦之所以相推而立也；雜卦者，卦之所以相錯而成也。相推故相因，相錯故相交，是六十四卦之所從出也。今將尋其流，探其源，而不知派之所從別，可乎？雖然，理則萬殊，其歸一揆，既曰相因，又曰相交，何也？曰：相因如一二，相交如奇偶。一之與二，乃其所以為奇偶，故不同於雅、頌、典、謨、訓誥之書。於其本篇，各冠以夫子之序，獨遺易而不取者，惑也。愚故仿彖、象之例，取序卦一篇，自屯而下，釋於逐卦之首，而雜卦之義，辨於爻象之前。至於本篇，自如其舊，學者得以考焉。屯：元亨利貞，勿用有攸往，利建侯。彖曰：屯，剛柔始交而難生，動乎險中，大亨貞。雷雨之動滿盈，天造草昧，宜建侯而不寧。稱天地之德曰「乾坤」，稱乾坤之德曰「元亨利貞」，無以加於此矣。屯之成卦，震下坎上，而稱其德亦曰「元亨利貞」，何也？曰：屯也者，乾坤變而其氣通也，是乃其所以為乾坤者也。其稱之盛，不亦宜乎？或曰：「震坎成卦而取諸乾坤以為義。」夫六十四象，孰非乾坤者？而「元亨利貞」獨稱於屯、臨、隨、無妄、革，何也？曰：之數卦者，各有其義，未暇悉數也。若夫屯者，震坎之所成也。震坎成而坤艮著，然後屯象立也。「震」為元，「坎」為亨、為利，「艮」為貞，始終之義備也。天氣下降，地氣上騰，乾之象見於三子，坤之象備於三爻，生成之義無不備矣。是故兼乎四德而稱之也。夫子釋之，言「大」而不言「元」，明其所自來也；言「亨」而不言「利」，明其兼之也。可謂晦而章矣。然而「勿用有攸往」，何也？曰：「震」一陽在下為始，又為動；坎一陽在中為通，又為險、為陷。故曰：「剛柔始交而難生，動乎險中。」夫險難在前，見利而動，未有無悔者也。故戒之曰：「勿用有攸往。」然而「利建侯」，何也？曰：「坤」者，乾之配也，代乾之主也。「震」、「坎」、「艮」者，乾之子也，成乾之用也。是故先王建邦設都，立之司牧，以長治之，君人者不勞而天下治矣，焉用攸往哉？夫「乾」之彖曰「元亨利貞」，而不曰「有攸往」者，君道也。「坤」之彖曰「元亨，利牝馬之貞，君子有攸往」者，臣道也。屯之彖曰「元亨利貞，勿用有攸往，利建侯」者，合而言之也。天下歸往謂之王，受君之民而為之牧，謂之侯伯。若皆不往，則險難無自而濟矣。故曰：「雷雨之動滿盈，天造草昧，宜建侯而不寧。」夫天之所為者，茫昧而不可知，其可見者，雷雨滿盈而已。是以「勿用有攸往」，而「利建侯」也。或曰：子以四象為義，而夫子之釋「彖曰」，但言雷雨而不及坤、艮，何哉？曰：夫子不云乎，易有四象，所以示也。夫震、坎者，所以為屯也。既已為屯矣，雖不言震、坎，可也。是故文王、周公但言屯而未嘗言震、坎也。坤也者，震、坎之所致養；艮者，震、坎之所終始也。既已為震、坎矣，雖不言坤、艮，可也。是故夫子言震、坎，而未嘗言坤、艮也。斯不亦舉一隅之意乎？學者苟以為不然，則震、坎之所以為屯，屯之所以為元、亨、利、貞，吾不知其何從而得此象，又系之以如此之辭也。象曰：雲雷，屯，君子以經綸。「雲雷」，「坎」、「震」也。「雲雷」者，所以為雨也。方其未雨也，滿盈乎天地之間，是以謂之屯也。君子觀此屯之象，以經綸天下之事業，猶雲與雷動，而膏澤隨之也。經綸之為言，組織之未成云爾。然經之綸之，所以為組織也，其亦云雷而未雨之義乎？或曰：雲雨皆坎也，不謂之雨而謂之雲，何也？曰：雨在雷上，雷至雨未至，是以謂之雲也。然而其彖又曰：「雲雷之動滿盈。」何也？曰：云為雨而未成者也，謂之雷雨之動，不亦可乎？既雨則解矣，而何滿盈之有哉？雜卦曰：「屯見而不失其居。」自坤而屯，初與五變，而三不變也。變於初而配在四，變於五而配在二，何不屯之有哉？三上不變，莫適為配，是其所以為屯也。三變則為既濟矣。夫陰陽相求，物之情也。三，陽位也。在屯之世，剛柔始交，民無定主，以六居之，能無爭乎？是以為屯。六三求於上六而弗之應，介於二四而莫之與，二將應五，四將應初，三為之難，是以謂之屯也。夫天無二日，民無二王，使三而不為之難，彼為二陽者，亦莫能相抑也。是故初以四為配而承於二，五以二為配而比於四，據兩立之𫝑，挾猜疑之情，其為屯難，不亦宜乎？然初與四、二與五，皆不失其正，而二五又中也。其在爻，初四有婚媾之利，二五有小大之屯，何也？曰：天地交而為泰，不交則為否。乾下於四，坤升於四，是以為見也。九五在上，六二在下，是以為屯也。此所謂見而不失其居者乎？初九：磐桓，利居貞，利建侯。象曰：雖「磐桓」，志行正也。以貴下賤，大得民也。初九，「震」也，以陽居剛，而在下卦之初，應乎六四而承乎六二，二爻皆「坤」，而四又「坎」也，故曰「磐桓」。說者謂「磐桓」為迴旋，失之矣。夫磐如磐，桓如桓。磐，大石也；桓，大木也。石磐於地，故謂之「磐」。易曰：「鴻漸於磐。」木亙於地，故謂之「桓」。詩曰「松柏桓桓」是也。「磐桓」與「介於石」之義同，謂居貞也。或曰：震為動、為躁，而取「磐桓」以為義，然則「艮」之象於何取之？曰：「艮」者，震之所自來也；震者，艮之所從出也。艮終而震始，艮少而震長。是故震為大塗，而艮為小石；震為蒼筤，而艮為堅節；震為重門，而艮為門闕，皆相因之義也。「豫」之六二，介於石者，「艮」也。其不終日者，出乎「震」也。今也震居坤下，三陰乘之，猶未離乎「艮」也，謂之「磐桓」，不亦宜乎？夫靜不極者其動不威，守不固者其發不勇，根不深者其末不茂，基不大者其上不廣。故曰：「利居貞，利建侯。」以九居初，正也。君子居得其正，民之所歸，是以能「建侯」也。居天下之廣居，行天下之大道，是之謂「居貞」也。有天下而君之，列爵分土，法制號令，我之自出，是以謂「建侯」也。故曰：「譬如北辰，居其所而眾星拱之。」彖所謂「勿用有攸往」是也。震為長男，有天子象；「坤」為臣妾，有諸侯萬民之象。方屯之初，婚媾未定，男不下女，無以得妻；君不下士，無以得臣。初九以陽下陰，以貴下賤，卑𫝑而尊賢，先人而後己，民之歸之，如水之就下。是故初體乎「震」，不得不上行；四體乎「坎」，不得不就下；上體乎「坤」，不得不順服。是以得民而建候也。故曰：「雖磐桓，志行正也；以貴下賤，大得民也。」六三，屯如邅如，乘馬班如，匪寇婚媾。女子貞不字，十年乃字。象曰：六二之難，乘剛也。「十年乃字」，反常也。六二，「坤」也。以陰居柔，而在下卦之中，應於九五而乘乎初九，二爻皆「震」也。承於六三，三則「艮」也，故曰「屯如邅如」。屯，難也。邅，回而不進也，故曰「乘馬班如」。春秋傳曰：「有班馬之聲。」杜氏曰：「班，別也。」乾為馬，馬，陽物也。震、坎、艮得乾之一體，是以皆稱之也。二之如初，非其所乘，是故有「班馬」之象。古者大事不乘異產。「乘馬班如」，其欲去之亟矣。然五在險中，四為之難，三方守之正，三遏其衝，故曰：「匪寇婚媾，女子貞不字。」四與上皆「坎」也，「坎」為盜，故有寇象。二五平應，匪寇之故，則「婚媾」矣。「婚媾」也者，言其以正合也。「女子」者，未嫁之稱也。六五居中守正，故有「女子」之象。然體「坤」而配五，又有為母之道焉。「字」，母道也。「婚媾」則「字」矣。既曰「婚媾」，又曰「不字」，何也？曰：夫婦之道，男先女，女乃從之；君臣之義，君先下士，士乃應之。合六五體震而止行，不肯下逮六二體坤而後和，莫敢先求。又有二爻實為之間，故雖「婚媾」既成，猶「十年」而「不字」也。夫士之仕，猶女之嫁也，不曰「士貞」而曰「女子貞」者，女子待禮而行，貞而不可犯，於士為猶嚴也。雖牝牡之情、室家之願，陽唱而陰和，男行而女從，自然之理也。方屯之時，陰陽相求，三字六正而有五為之配，其終「不字」而已乎？故曰：「十年乃字。」十者，數之終也，大運之行也。數終必變，運周必復。二五相易，「婚媾」字矣。雷雨作解，其十年之數乎？故子曰：「六二之難，乘剛也。十年乃字，反常也。」六三：即鹿無虞，惟入於林中。君子幾，不如舍，往吝。象曰：「即鹿無虞」，以從禽也。君子舍之，「往吝」窮也。六三以陰居剛，而在下卦之上，上體為「艮」，下體亦為「艮」，而介乎二四之坤，應在上六，上為坎，又陰象也。故曰：「即鹿無虞，惟入於林中」。「震」「坎」重而「坤」「艮」具，動乎險中，所以為屯也。坎「艮」成而隱伏，鹿之象也。「坤」為眾，林中之象也。三非陽也，而居於剛，自以為陽，而求配於上六。六不之應，而介乎二四之間，無德而求民者也。平世之民，以魚為喻，亂世之民，以鹿為喻，善走而難馴也。山林榛莽，獸之窟宅，虞人知之。無德而求民，猶無虞而即鹿也。夫初九之為六二，皆有其德而得其配，故以婚媾言之。詩曰：「娶妻如之何？匪媒不得。」取之有媒，猶田之有虞也。故田者必以虞人為指。苟無虞而田，無媒而娶，皆寇也。故曰：「君子舍之，往吝窮也」。舍，止也。吝，羞也。「艮」在坎下，見險而能止者也。即鹿而無虞，鹿不可得，而入於林莽之中矣。苟貪利而忘義，險在前而不顧，其自取困窮之羞，不亦宜乎？故子曰：「即鹿無虞，以從禽也。君子舍之，往吝窮也。」或雲：別本「以從禽也」上有「何」字，當從之。「君子舍之往吝」為句。六四：乘馬班如，求婚媾。往吉，無不利。象曰：求而往，明也。六四以陰居柔，而在上卦之下，上體為「坎」，下體為「坤」，應乎初九之「震」，而乘六三之「艮」，故曰「乘馬班如」。屯惟二陽，而三爻皆言「乘馬」者，明三體「艮」而居剛，有為君之志也。四配在初而乘乎三，以其所乘，故亦有「班如」之象也。「乘馬班如」，則必舍之而從初矣，故曰「求婚媾」。「往」，求初也。往者四也。男先下女，女乃從之；君先下士，士乃應之。求而不往則失君，不求而往則失臣，二者皆過也。初九以陽而下陰，體「震」而上行，先求之義也。六四以陰而從陽，體「坎」而就下，後往之義也。故曰：「吉無不利。」男女皆正而家以肥，君臣皆正而國以治，如是之「吉」，而有不利乎哉？故子曰：「求而往，明也。」君臣之間，夫婦之際，而可以不明乎哉？初九「震」為「明」，六三「艮」為幽。二爻見求，而四之所往者明也。九五：屯其膏，小貞吉，大貞兇。象曰：「屯其膏」，施未光也。九五，「震」也，以陽居剛而在上卦之中，應乎六二之「坤」，而乘承皆「坎」也，故曰：「屯其膏」。「震」為雷，「坎」為雨，膏澤之象也。「坤」為主，為民，震為上行，膏澤不下於下之象也。五配在二，而莫肯相求，是以屯其膏而不下也。陽為大，陰為小。大者，五也，君道也，夫道也；小者，二也，妻道也，臣道也。五，正也，二亦正也。然女不求男，不失其為女；士不求君，不失其為士。小者以是為正，則吉矣。男不下女，旡以成其家；君不下士，旡以保其國。大者以是為正，莫之與矣。欲旡兇，得乎？故初與五同於體「震」，二與四同於體「坤」，謂之「婚媾」，而或利或屯者，升降之不同也。然雲雷之盈，其終必雨。二五反常，「十年乃字」，其雷雨作解之象乎？故子曰：「屯其膏，施未光也。」上六：乘馬班如，泣血漣如。象曰：「泣血漣如」，何可長也？上六之象，以陰居柔，而在上卦之上，應在六三而乘九五之「震」，故曰「乘馬班如」。上之與五，非其所乘，故亦有「班如」之象。然二舍其班而適五，四舍其班而適初，各從其偶也。上六舍其班而適三，三陰柔而體「艮」，非其偶也，故曰「泣血漣如」。「坎」為憂傷，為心病，為血卦，故有「泣血」之象。上六正反皆「坎」，則「漣如」之象也。居屯之極，與五為鄰，舍之而去，悵悵然旡所之，途窮泣血，不亦宜乎？序卦曰：屯者，物之始生也。物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。蒙之成卦，屯之反也。覆而視屯，蒙之象也。乾坤之交，由震而達乎坎，由坎而終乎艮，則屯蒙之序也。夫蒙者，冥昧之稱也，掩蔽之義也。萬物之生，受陰陽之氣，雜乎芒芴之間，謂之屯。勾萌胎卵，有生而未達，襁褓覆翼，有識而未開，則謂之蒙。不屯則不生，不蒙則不成。是故屯之彖曰：「元亨，利貞。」蒙之彖不曰「元」而曰「亨利貞」，於義昭矣。蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。彖曰：蒙，山下有險，險而止，蒙。蒙亨，以亨行，時中也。匪我求童蒙，童蒙求我，志應也。初筮告，以剛中也；再三瀆，瀆則不告，瀆蒙也。蒙以養正，聖功也。下坎上震，成卦曰「蒙」者，坎為水，艮為山，坤為地，艮為山，為止。水出於地而山止之，故謂之蒙。險陷之中，進而上行，有物止而蒙之象也。夫子但取其二象而釋之曰：「山下有險，險而止，蒙。」夫險能不出，此其所以為蒙也。是故謂之「童蒙」，謂之「蒙暗」，謂之「蒙蔀」。今曰「蒙亨」，何也？曰：蒙亨，蒙而求亨也，非謂蒙者有時而亨也。凡物之生，形氣未定，無以蒙之，則暴露散越而不能以條暢遂茂。人之聰明亦如是爾。仁、義、禮、智，性所有也。發而不中節，則流而入於邪。養之以正，若火之始然，泉之始達矣。故曰：「蒙亨，以亨行，時中也。」以亨行者，因其𫝑而利導之，非揠苗而助之長也。發而中節，不亦宜乎？匪我求童蒙，童蒙求我。何也？曰：蒙之諸爻，以上蒙下為義。其二陽，先覺之象；其四陰，童蒙之象也。陽為明，陰為晦；上為應，下為求。初六之蒙，九二發之；六五之蒙，上九擊之。童蒙求我也。三之不順，四之獨遠，匪我求童蒙也。君子之教也，來者弗距，去者弗追，人之求我，斯應之矣。彼不我求，吾曷為即之哉？故曰：「匪我求童蒙，童蒙求我，志應也。」志於應而已，不志於求也。初筮告，再三瀆，瀆則不告。初之與二，五之與上，求則得之，皆初筮也。三四之於上，歷二三爻，求而弗應，再三瀆也。筮者，所以求疑也，齊戒以奉之，肅恭以臨之，弗敢瀆之。初筮而不從，又求改筮，至於再，至於三，神弗之告矣。詩云：「我龜既厭，不我告猶。」君子之教也，與其進，不與其退。人潔已以進，斯告之矣。不憤不啟，不悱不發，學而弗志，問而弗思，誨爾諄諱，聽我藐藐，又從而告之，祗所以瀆之也。故曰：「初筮告，以剛中也。」「再三瀆，瀆則不告」，瀆蒙也。或曰：二之位，剛中固也。上九亦曰「剛中」，何哉？曰：此之謂時中也。初六以不中而震坤遇險而止，所以為蒙也。今因蒙之初，以陰求九二，故九二以中而發之。六五之童蒙，未失乎中也，故上九為之「禦寇」而已。「禦寇」者，閒邪之義也。然則九二之為「剛中」，六五之謂「時中」，其於初筮告，以亨行，均也。夫子之言，蓋互明矣。「利貞」，何也？曰：亨而利，利而正，乾坤之序也。通乎坎，成乎艮，故系之也。喜怒哀樂未發，謂之中，發而皆中節，謂之和。惟精惟一，允執厥中。故曰：「蒙以養正，聖功也。」洪範：「聖，時風若；蒙，恆風若。」夫聖與蒙反象也，可不深求其義乎？象曰：山下出泉，蒙；君子以果行育德。山，艮也；泉，坎也。坎不曰「水」而曰「泉」者，水在山下，泉之象也。泉出於山，土石蒙之，其源濫觴，其及遠也，無所不至，故君子以之「果行育德」。「果行」者，猶其不捨晝夜也；「育德」者，猶其源深而流長也。孟子曰：「源泉混混，不捨晝夜。」盈科而後進，放乎四海。有本者如是，是之取爾。其山下出泉，果行育德之義乎？雜卦曰：「蒙雜而著。」蒙者，蒙也。蒙之言覆也，故爻以上蒙下為義。日出而明，入而晦，故陽為明，陰為蒙。蒙者必求於人，求人者未有不下之者也。故下為求，上為應。中也養不中，才也養不才。故以陽居柔者，人之所求也。若以陽居剛，則為獨善其身，非蒙之所賴也。以陰居柔，剛困而不舉者，終於蒙而已矣。故曰：「蒙雜而著」，此之謂也。今夫蒙者，「坎」「艮」之所成也。坎為幽，比方之卦也；艮為土，東北之卦也。自坎而徂艮，則為蒙；自艮而徂震，則為明矣。然則坎從艮，非求艮也，將以求震也。震也者，艮之反也。入乎坎而不止乎艮，則何以能出乎震哉？是故蒙之陰爻，「坎」、「坤」、「艮」也；其陽爻，皆「震」也。此則童蒙之所以來我者也。或問：「說卦：離為明，今謂震為明，何也？」曰：「離也者，日中之明也；震也者，日出之明也。蒙之求明，猶夜之求旦也，而豈日中為義乎？」初六：發矇，利用刑人，用說桎梏，以往，吝。象曰：「利用刑人」，以正法也。初六，「坎」也。以陰居剛，而在一卦之下，承於九二之震，其應六四，四則「艮」也，故曰「發矇」。坎為幽，震為明，以幽求明，發矇之象也。在卦之下，下愚之品，聰明不開，恣於情慾，放僻邪侈，無不為矣，故曰：「利用刑人。」陰為刑，坎為陷，陷於刑者，皆蒙象也。震為動，為決躁。刑，刑人之象也。夫不教而殺，謂之虐，今蒙之初，不教而刑之，何也？曰：陽為德，陽為刑。震主施惠，坎主幽陷，陽以坎從震，用刑輔德者也，故曰「利」。利也者，非以刑殺人為利也，製為之刑，以杜其非心，加之明刑，以冀其悛革，斯為利也。若有罪而刑殺，又何利之有哉？或曰：刑一人而千萬人服，豈非利乎？曰：不然者也。刑所以利民也，非毒民而以自利也。若刑殺人、劓人，刑人而我以為利，是誠何心哉？故曰「用說桎梏以往」。各坎為矯輮，故有「桎梏」之象。震為出，故有說而往之象。荀氏說卦：「坎為桎梏。」桎梏者，所以械其首足也。夫用刑，然後說之以往。周官：大司寇以圜土聚教罷民，見害人者，弗為寇飾，而加明刑焉。其不能改而出圜土者，殺。又以嘉石平罷民，凡民之有罪而未麗於法者，桎梏而坐諸嘉石，役諸司空，使州里任之，然後宥而舍之。所謂「說桎梏以往」者，不能改而出圜土者也。於是而用刑焉，一成而不可變者也。死者不能復生，斷者不可復續，聖人之所不忍也，故曰「吝」。立法制用於加桎梏之前，可謂利矣。刑殺劓用於「說桎梏」之後，亦有吝乎？「吝」之言「羞」者，夫豈特罷民之羞？為政者不能使民遷善改惡，而至於用刑，亦可羞矣。故子曰：「利用刑人，以正法也。」舜之命皋陶曰：「汝作士，明於五刑，以弼五教，期予於治。」刑期於無刑者也。甫刑曰：「伯夷降典，折民惟刑。」「士制百姓於刑之中，以教祗德。」皆正法之謂也，而豈以刑殺人為利哉？九二：包蒙，吉。納婦，吉，子克家。象曰：「子克家」，剛柔接也。九二，「震」也。以陽居柔而在下卦之中，應乎六五而介於初、三，二爻皆「坎」，而三又「坤」也，故曰「包蒙」。「包」，覆藏也。「坎」為隱伏，故有「包蒙」之象。以陽明之資，震動之體，而在陰柔險陷之中，以蒙自包者也。君子之道，「闇然而日章」，有諸中而形諸外，故曰「吉」。然乘乎初六，有發矇之象，故又曰：「納婦吉」。「婦」謂初也。婦之初歸，未習夫家之事，童蒙也納而教之，正法以刑之，辨之於早，不亦「吉」乎？詩曰：「刑于寡妻。」書曰：「觀厥刑于二女。」皆此之謂也。故曰「子克家」。「震」，長子也，能教其婦，斯克其家矣。或曰：「二配在五，不以五為婦乎？」曰：「蒙以上下為義，五居尊，非婦也。」曰：「然則六五為父，九二為子乎？」曰：非也。對子而言，則父剛而子柔。今子克家，而父為童蒙，吾未之聞矣。父在，觀其志；父沒，觀其行。今父在而言克家，吾亦未之聞矣。曰：然則九二何從而稱子乎？曰：五體「坤」，「坤」為母，陰柔居尊，群蒙所附，非得九二剛中之子，何以克其家乎？故子曰：「克家，剛柔接也。」言九二以剛明之才，上接六五而任其任；六五以柔順之德，下接九二而行其道，是以能克家也。「坎」六四之象曰「剛柔際」者，明二爻之象。此言「剛柔接」者，明上下之象也。豈一時之苟指哉？六三：勿用取女，見金夫，不有躬，無攸利。象曰：「勿用取女」，行不順也。六三上體為「坤」，下體為「坎」，以陰居剛而在下卦之上，應乎上九而乘乎九二，二爻皆「震」也。承於六四，四則「艮」也，故曰：「勿用取女」。以陰居剛，體「坤」而「離」乎「坎」，近九二而下比之，女之不可取者也，故曰：「見金夫，不有躬，無攸利」。「金」者，剛也。三之稱金，猶其稱馬也，皆得「乾」之一體故也。夫之吉，配也。三配在上而比於二，見剛夫而求之，不自有其身者，女之醜行也。敗國亂家，皆是物也，何所往而利哉？或曰：何以知三之不待配而從二乎？曰：為其「坎」也。坎為水，水性趨下而乘乎二，其求之也，孰御之哉？故子曰：「勿用取女，行不順也。」三體「坤」，「坤」為順。今雜乎「坎」而為不順之行，是以聖人戒之也。六四：困蒙，吝。象曰：困蒙之「吝」，獨遠實也。六四正反皆「艮」也。以陰居柔而在上卦之下，介於三、五之間。三與五皆「坤」，而初與二皆「坎」也，故曰「困蒙」。「坤」為黑，「坎」為幽，「艮」為止，相與為闇昧者也。困而不舉，斯為下矣。楊雄有言：「侍於君子，晦斯光，窒斯通。」今六四以陰柔之質，而上下無陽，不能近乎君子矣。其困不亦宜乎？故曰「吝」。書曰：「遠耆德，比頑童。」是已。子曰：「困蒙之吝，獨遠實也。」陽為實，陰為虛。實，故有以分人；虛，故可以受道。六四以陰居柔，而在三陰之中，獨遠於陽，宜其吝也。六五：童蒙，吉。象曰：「童蒙」之吉，順以巽也。六五，「坤」也，以陰居剛而在上卦之中，隱乎九二而承於上九，二爻皆震也，故曰「童蒙」。坤為順，震為明，以順求明，「童蒙」之象也。禮曰：「喜怒哀樂未發之謂中。」六五是也。或曰：「六五之蒙，有以異於初六乎？」曰：是何言與？初居最下，下德之質也；五居尊位，而以中行，上智之資也。上智之資而謂之「童蒙」，何也？曰：童蒙者，求人也。禮恭，然後可以言道之方；辭順，然後可以言道之理；色從，然後可以言道之致。夫如是，四海之內，皆將輕千里而來告之以善，故曰「吉」。高宗之誥曰：「以臺正於四方，臺恐德弗類。」成王之誥曰：「維予小子，不聰敬止。」此之謂「童蒙」也。終始典於學，厥修德罔覺，日就月將，學有緝熙於光明，斯之謂「吉」矣。子曰：童蒙之吉，順以巽也。「坤」為順，因其𫝑而利導之，非勉強而行之者也。故夫九二、上九皆「震」也，而初六則「坎」也，六五則「坤」也。「坤」為黑，「坎」為幽，其為蒙一也。而「坎」為險，坤為順，此其所以不同歟？或曰：子以初為下愚，五為上智，三、四者，中人之性歟？曰：然。然則中人以下，六三是也；中人以上，六四是也。曷為其困且吝也？曰：三舍順而效逆，四遠賢而比愚，其不可以語上，均矣。困且吝，宜哉！上九：擊蒙，不利為寇，利禦寇。象曰：利用「禦寇」，上下順也。上九，「震」也。以陽居柔，而在一卦之上，應於六三而乘乎六五，二爻皆「坤」，而三又「坎」也，故曰「擊蒙」。說者皆以「擊蒙」為征伐之義，非也。夫既謂之蒙矣，雖不帥教，豈能得與我敵也哉？教之弗帥，君子猶矜其愚而將宥之，不得已而後刑之，則初六之「刑人」是也。何至於與師動眾，以力勝之乎？或曰：然則擊蒙何義也？曰：擊如擊鼓、擊磬之擊。陽者，陰之所求也；明者，暗之所求也。「震」為聲，為動，故有擊蒙之象。瞽者不見泰山，聾者不聞雷霆，下愚之質也。發之而後耳有聞，目有見。初六謂之發矇，叩之小則小鳴，叩之大則大鳴，上智之資也。觸之而無不應，故六五謂之「童蒙」。夫五以柔居尊，委聽於上，其終為聖、為蒙，在上九所以擊之何如耳？故曰：「不利為寇，利禦寇。」格其非心，引之於當道，所謂「禦寇」也；逢君之惡，納之於邪，所謂為寇也。有禦寇之臣，則五為信順尚賢之君。有為寇之臣，則五為闇弱失權之主。然則當其任者，其非伊傳周公而誰可乎？管蔡之流言曰：「公不利於孺子。」此則為寇也。「周公東征，四國是皇。」此則禦寇也。孟子曰：「有伊尹之志則可，無伊尹之志，則篡也。」或曰：上九一爻，兼有為寇、禦寇之象乎？曰：有之。六三，坎也。坎為寇，有不順之行，上與之配，若不從之，是與之為寇矣。拒而不以刑御之，何以知其有利不利乎？曰：三以小人而乘君子之器，既無攸利矣。上而從之，又何利之有焉？故三言「勿用取女」，上言「不利為寇」，可謂深切著明矣。子曰：「利用禦寇，上下順也。」上為六五，下為六三，上下二爻皆有坤順之體。故上九系之而無不應，御之而無不服。功成於外，而人主不疑；委任於中，而天下不議。此非人臣之利，天下國家之利也。六五不順，雖欲禦寇，不可得矣；六三不順，雖欲擊蒙，又可得乎？周公所以居東三年，而作鴟鶚之詩，以遺成王也。周易經傳集解卷二，",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
